(function(root){
const seed={id:'DEMO-INV-01',employer:'Almacén Demo (ficticio)',role:'Auxiliar de inventarios',capacity:2,committed:true,formalExperience:false,expired:false};
const example={problem:'En un negocio familiar ficticio, el registro mostraba más unidades que el conteo físico.',contribution:'Comparé el registro con el conteo y propuse revisar movimientos antes de cambiar el inventario. Mi aportación fue detectar la diferencia y explicar por qué debía investigarse.',record:50,count:48,result:'Detecté una diferencia de 2 unidades. No puedo afirmar que mi propuesta redujo pérdidas.',type:'unverified'};
function commitment(s){return {...seed,committed:s!=='none',capacity:s==='full'?0:2,formalExperience:s==='barrier',expired:s==='expired'};}
function gate(c){if(!c.committed)return 'No existe un compromiso: no prepares evidencia.';if(c.formalExperience)return 'El empleador incumple al exigir experiencia formal. La oportunidad queda bloqueada.';if(c.expired)return 'El compromiso venció. No prepares evidencia hasta renovarlo.';if(c.capacity<1)return 'No hay cupos comprometidos. No prepares otra prueba.';return '';}
function validate(e){for(const [key,max] of [['problem',500],['contribution',700],['result',500]])if(typeof e[key]!=='string'||e[key].trim().length<20||e[key].length>max)return 'Explica cada respuesta con entre 20 caracteres y su límite indicado.';for(const key of ['record','count'])if(!Number.isInteger(e[key])||e[key]<0||e[key]>100000)return 'Usa cantidades enteras entre 0 y 100,000.';if(!['unverified','simulation','demo-record'].includes(e.type))return 'Selecciona un respaldo válido.';return '';}
function provenance(e){return e.type==='simulation'?'Simulación: no verifica una mejora real':e.type==='demo-record'?'Cálculo verificado contra datos ficticios del demo; resultado laboral no verificado':'Resultado no verificado; la habilidad se evalúa por separado';}
function decide(state,criteria,reason,condition){if(state.reserved)return {status:'blocked',text:'Ya existe una entrevista simulada reservada. No se descuenta otro cupo.'};if(reason.trim().length<20||reason.length>700)return {error:'La razón debe tener entre 20 y 700 caracteres.'};if(condition==='unpaid')return {status:'paused',text:'Evaluación pausada. El trabajo nuevo que la empresa utilizaría requiere un acuerdo de pago separado.'};const c={...state.commitment,...(condition==='full'?{capacity:0}:condition==='barrier'?{formalExperience:true}:{})};const blocked=gate(c);if(blocked)return {status:'blocked',text:blocked};if(!criteria.every(Boolean))return {status:'feedback',text:'No se cumplen todos los criterios todavía. Revisa la razón específica y solicita una segunda revisión si discrepas.'};return {status:'interview',text:'Entrevista simulada habilitada: 15 minutos. En el piloto real, el empleador debe confirmar fecha y responder en 2 días hábiles. No garantiza contratación.',capacity:c.capacity-1};}
const api={seed,example,commitment,gate,validate,provenance,decide};if(typeof module!=='undefined')module.exports=api;root.FP=api;
})(typeof globalThis!=='undefined'?globalThis:this);
